     "summary": "9月24日，Omdia最新数据，2026年第二季度，中国大陆PC出货量同比增长11%，达到1140万台。其中，台式机出货量大幅增长42%，抵消了笔记本电脑出货量2%的下降，二者出货量分别为430万台和710万台。与此同时，受需求疲软及持续的供应挑战影响，中国大陆平板电脑出货量同比下降13%，至800万台。（文章来源：界面新闻）",
